/**
 * Render ikon lucide.
 *
 * @param string $name  Nama ikon, contoh: 'phone', 'map-pin', 'circle-check'.
 * @param string $class Kelas Tailwind untuk ukuran/warna, contoh: 'h-4 w-4 text-jipo-blue'.
 */
function icon(string $name, string $class = 'h-4 w-4'): string
{
    $icons = $GLOBALS['LUCIDE_ICONS'] ?? [];
    $inner = $icons[$name] ?? '';

    return '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"'
        . ' fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"'
        . ' stroke-linejoin="round" class="lucide lucide-' . e($name) . ' ' . e($class) . '"'
        . ' aria-hidden="true">' . $inner . '</svg>';
}
